package com.aurum.scalp;

import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class ZoneEngineTest {
    private static final long T=1_767_225_600_000L;
    private static List<Market.Candle> waves(Market.Frame f,int count){List<Market.Candle> b=new ArrayList<>();for(int i=0;i<count;i++){double c=4000+6*Math.sin(i*Math.PI/6);b.add(new Market.Candle(T+i*f.duration(),c,c+1,c-1,c));}return b;}
    private static ZoneEngine.Analysis analyse(List<Market.Candle> b,Market.Frame f){return ZoneEngine.calculate(b,f,b.get(b.size()-1).time+f.duration());}
    private static void append(List<Market.Candle> b,Market.Frame f,double price){b.add(new Market.Candle(b.get(b.size()-1).time+f.duration(),price,price+1,price-1,price));}
    @Test public void candlesRejectMalformedFutureDuplicatesAndSort(){List<Market.Candle> b=waves(Market.Frame.M5,6);List<Market.Candle> in=new ArrayList<>(b);in.add(b.get(1));in.add(new Market.Candle(T+Market.Frame.M5.duration(),4000,3900,4100,4000));Collections.reverse(in);List<Market.Candle> clean=Market.closed(in,Market.Frame.M5.duration(),T+5*Market.Frame.M5.duration());assertEquals(5,clean.size());assertEquals(T,clean.get(0).time);}
    @Test public void timestampsMustAlignToFrame(){List<Market.Candle> b=new ArrayList<>();b.add(new Market.Candle(T+1000,4000,4001,3999,4000));assertTrue(Market.closed(b,Market.Frame.M5.duration(),T+1_000_000).isEmpty());}
    @Test public void wilderAtrIncludesContinuousPriceJumps(){List<Market.Candle> b=new ArrayList<>();for(int i=0;i<14;i++)b.add(new Market.Candle(T+i*60_000,4000,4001,3999,4000));assertEquals(2,ZoneEngine.atrSeries(b,Market.MINUTE)[13],.0001);b.add(new Market.Candle(T+14*60_000,4010,4011,4009,4010));assertEquals((26+11)/14.0,ZoneEngine.atrSeries(b,Market.MINUTE)[14],.0001);}
    @Test public void confirmedSwingsNeedLaterClosedBars(){Market.Frame f=Market.Frame.M5;List<Market.Candle> b=waves(f,80);b.add(new Market.Candle(T+80*f.duration(),4000,4050,3999,4000));assertTrue(analyse(b,f).zones.stream().noneMatch(z->z.center>4040));append(b,f,4000);append(b,f,4000);assertTrue(analyse(b,f).zones.stream().anyMatch(z->z.center>4040));}
    @Test public void futureCandleCannotChangeCurrentAnalysis(){Market.Frame f=Market.Frame.M5;List<Market.Candle> b=waves(f,100);long cutoff=T+100*f.duration();ZoneEngine.Analysis before=ZoneEngine.calculate(b,f,cutoff);b.add(new Market.Candle(cutoff,4000,5000,3000,4500));ZoneEngine.Analysis after=ZoneEngine.calculate(b,f,cutoff);assertEquals(before.zones.size(),after.zones.size());assertEquals(before.atr,after.atr,0);for(int i=0;i<before.zones.size();i++)assertEquals(before.zones.get(i).center,after.zones.get(i).center,0);}
    @Test public void confirmationsDoNotBridgeSessionGaps(){Market.Frame f=Market.Frame.M5;List<Market.Candle> b=waves(f,50);b.set(48,new Market.Candle(T+48*f.duration(),4000,4050,3999,4000));Market.Candle last=b.get(49);b.set(49,new Market.Candle(last.time+f.duration(),last.open,last.high,last.low,last.close));assertTrue(analyse(b,f).zones.stream().noneMatch(z->z.center>4040));}
    @Test public void repeatedWavesCountSeparateConfirmedReactions(){ZoneEngine.Analysis a=analyse(waves(Market.Frame.M5,120),Market.Frame.M5);assertTrue(a.zones.stream().anyMatch(z->z.support&&z.tests>=3));for(ZoneEngine.Zone z:a.zones)assertFalse(z.reference);}
    @Test public void zoneWidthsAreBoundedForEveryFrame(){for(Market.Frame f:Market.Frame.values()){List<Market.Candle> b=new ArrayList<>();for(int i=0;i<250;i++){double c=4000+7*Math.sin(i*Math.PI/6)+i*.012;b.add(new Market.Candle(T+i*f.duration(),c,c+.6,c-.6,c));}ZoneEngine.Analysis a=analyse(b,f);assertFalse(a.zones.isEmpty());for(ZoneEngine.Zone z:a.zones)assertTrue(f.label+" width "+z.width(),z.width()<=z.cap+.000001);}}
    @Test public void aVolatilitySpikeDoesNotWidenExistingBands(){Market.Frame f=Market.Frame.M5;List<Market.Candle> b=waves(f,120);ZoneEngine.Analysis before=analyse(b,f);long time=b.get(b.size()-1).time+f.duration();b.add(new Market.Candle(time,4000,4100,3900,4000));ZoneEngine.Analysis after=analyse(b,f);int shared=0;for(ZoneEngine.Zone z:before.zones)for(ZoneEngine.Zone q:after.zones)if(z.lastTest==q.lastTest&&z.support==q.support){assertEquals(z.low,q.low,0);assertEquals(z.high,q.high,0);assertEquals(z.cap,q.cap,0);shared++;}assertTrue(shared>0);}
    @Test public void twoClosesInvalidateOldSupport(){Market.Frame f=Market.Frame.M5;List<Market.Candle> b=waves(f,80);append(b,f,3990);append(b,f,3989);ZoneEngine.Analysis a=analyse(b,f);assertTrue(a.brokenCount>0);assertTrue(a.zones.stream().noneMatch(z->z.support&&Math.abs(z.center-3993)<.5));assertTrue(a.watchZones.stream().anyMatch(z->!z.support&&Math.abs(z.center-3993)<.5&&z.reference&&z.tests==0));}
    @Test public void oneCloseIsBreakWatchNotAutomaticRoleReversal(){Market.Frame f=Market.Frame.M5;List<Market.Candle> b=waves(f,80);append(b,f,3990);ZoneEngine.Analysis a=analyse(b,f);assertTrue(a.zones.stream().anyMatch(z->z.support&&Math.abs(z.center-3993)<.5));assertTrue(a.nearest(3990,true,6,false).stream().noneMatch(z->Math.abs(z.center-3993)<.5));}
    @Test public void flippedRoleRequiresNewRetestAndResetsCounts(){Market.Frame f=Market.Frame.M5;List<Market.Candle> b=waves(f,80);for(double p:new double[]{3990,3989,3991,3992,3990,3989})append(b,f,p);ZoneEngine.Analysis a=analyse(b,f);ZoneEngine.Zone flipped=a.zones.stream().filter(z->!z.support&&z.flipped&&Math.abs(z.center-3993)<.5).findFirst().orElseThrow();assertEquals(1,flipped.tests);assertFalse(flipped.reference);}
    @Test public void downtrendDoesNotGeneratePsychologicalSupports(){Market.Frame f=Market.Frame.M1;List<Market.Candle> b=new ArrayList<>();for(int i=0;i<320;i++){double c=3320-i;b.add(new Market.Candle(T+i*f.duration(),c,c+1,c-1,c));}ZoneEngine.Analysis a=analyse(b,f);List<ZoneEngine.Zone> s=a.nearest(3001,true,5,true);assertEquals(1,s.size());assertTrue(s.get(0).reference);assertEquals(3000,s.get(0).center,.00001);assertEquals(0,s.get(0).tests);assertTrue(a.nearest(2900,true,5,true).isEmpty());}
    @Test public void rangeReferenceDoesNotGetConfluenceEvidence(){Market.Frame f=Market.Frame.M1;List<Market.Candle> b=new ArrayList<>();for(int i=0;i<80;i++){double c=4080-i;b.add(new Market.Candle(T+i*f.duration(),c,c+1,c-1,c));}ZoneEngine.Analysis a=analyse(b,f);ZoneEngine.Zone z=a.nearest(4001,true,1,true).get(0);assertTrue(z.reference);assertEquals("",ZoneEngine.context(z,Collections.singletonList(a)));}
    @Test public void nearbySelectionUsesBandEdgeDistance(){ZoneEngine.Analysis a=analyse(waves(Market.Frame.M5,100),Market.Frame.M5);ZoneEngine.Zone z=a.zones.stream().filter(q->q.support).findFirst().orElseThrow();assertEquals(0,z.distance(z.center),0);assertEquals(3,z.distance(z.high+3),.000001);assertFalse(z.validSide(z.low-1));}
    @Test public void insufficientAndFlatHistoryProduceNoFabricatedLevels(){assertTrue(analyse(waves(Market.Frame.M1,20),Market.Frame.M1).zones.isEmpty());List<Market.Candle> b=new ArrayList<>();for(int i=0;i<80;i++)b.add(new Market.Candle(T+i*60_000,4000,4000,4000,4000));ZoneEngine.Analysis a=analyse(b,Market.Frame.M1);assertTrue(a.zones.isEmpty());assertTrue(a.nearest(4000,true,3,true).isEmpty());}
    @Test public void invalidQuotesAreRejected(){assertFalse(new Market.Quote(T,4001,4000).valid());assertFalse(new Market.Quote(T,Double.NaN,4000).valid());assertFalse(new Market.Quote(T,4000,5000).valid());assertTrue(new Market.Quote(T,4000,4000.5).valid());}
    @Test public void freshnessUsesProviderCandleClose(){Market.Frame f=Market.Frame.M1;List<Market.Candle> b=waves(f,80);ZoneEngine.Analysis a=analyse(b,f);long close=T+80*f.duration();assertTrue(a.historyFresh(close+f.duration()));assertFalse(a.historyFresh(close+3*f.duration()));}
    @Test public void nearerActualWatchIsVisibleWithoutBecomingConfirmed(){
        Market.Frame f=Market.Frame.H1;ZoneEngine.Zone active=new ZoneEngine.Zone(f,3899,3901,3,true,false,false,2,T,T);
        ZoneEngine.Zone watch=new ZoneEngine.Zone(f,3994,3996,3,true,true,false,0,T,T,true);
        ZoneEngine.Analysis a=new ZoneEngine.Analysis(f,Collections.emptyList(),Collections.singletonList(active),Collections.singletonList(watch),20,1,"Mixed");
        assertTrue(a.nearest(4000,true,1,true).get(0).retestWatch);assertFalse(a.nearest(4000,true,1,false).get(0).reference);assertEquals(0,watch.tests);assertEquals("",ZoneEngine.context(watch,Collections.singletonList(a)));
    }
    private static List<Market.Candle> overnight(boolean unexpectedHole){
        long start=java.time.Instant.parse("2026-11-09T00:00:00Z").toEpochMilli(),end=java.time.Instant.parse("2026-11-11T02:00:00Z").toEpochMilli(),spike=java.time.Instant.parse("2026-11-10T21:00:00Z").toEpochMilli();List<Market.Candle> b=new ArrayList<>();
        for(long t=start;t<end;t+=Market.Frame.H1.duration()){int h=java.time.Instant.ofEpochMilli(t).atZone(java.time.ZoneOffset.UTC).getHour();if(h==22||(unexpectedHole&&t==spike-Market.Frame.H1.duration()))continue;b.add(new Market.Candle(t,4000,t==spike?4050:4001,3999,4000));}return b;
    }
    @Test public void knownOvernightClosureDoesNotEraseHourlySwing(){List<Market.Candle> b=overnight(false);ZoneEngine.Analysis a=analyse(b,Market.Frame.H1);assertTrue(a.zones.stream().anyMatch(z->!z.support&&Math.abs(z.center-4050)<.01));}
    @Test public void unexpectedMacroDataHoleStillRejectsConfirmation(){List<Market.Candle> b=overnight(true);ZoneEngine.Analysis a=analyse(b,Market.Frame.H1);assertTrue(a.zones.stream().noneMatch(z->Math.abs(z.center-4050)<.01));}
    @Test public void nativeFourHourWeekendBarsRemainValidForSwings(){
        long start=java.time.Instant.parse("2026-10-26T00:00:00Z").toEpochMilli(),end=java.time.Instant.parse("2026-11-09T04:00:00Z").toEpochMilli(),spike=java.time.Instant.parse("2026-11-06T20:00:00Z").toEpochMilli();List<Market.Candle> b=new ArrayList<>();
        for(long t=start;t<end;t+=Market.Frame.H4.duration()){java.time.ZonedDateTime d=java.time.Instant.ofEpochMilli(t).atZone(java.time.ZoneOffset.UTC);if(d.getDayOfWeek()==java.time.DayOfWeek.SATURDAY||(d.getDayOfWeek()==java.time.DayOfWeek.SUNDAY&&d.getHour()!=20))continue;b.add(new Market.Candle(t,4000,t==spike?4100:4001,3999,4000));}
        ZoneEngine.Analysis a=analyse(b,Market.Frame.H4);ZoneEngine.Zone z=a.zones.stream().filter(q->!q.support&&Math.abs(q.center-4100)<.01).findFirst().orElseThrow();assertEquals(end,z.confirmedAt);
    }
}
